import re
text='```py\nfirst\n```\n```py\nlast\n```'
m=re.findall(r'```[^\n`]*\n(.*?)```',text,re.DOTALL)
for cmd in ['/cc','/cc 2','/cc 99','/cc 0','/cc -1','/cc -2','/cc  2']:
 c=cmd.strip().split(' ')
 try: n=int(c[1])
 except: n=1
 if n>len(m): n=len(m)
 try: out=m[-n].strip()
 except IndexError: out='IndexError'
 print(repr(cmd),repr(out))

